namespace ToneCustoms.ShellStudio.Editor;
public sealed class Viewport3DControl:Grid { readonly Viewport3D view=new();readonly Model3DGroup scene=new();readonly PerspectiveCamera camera=new(){FieldOfView=55,Position=new Point3D(10,-12,9),LookDirection=new Vector3D(-10,12,-7),UpDirection=new Vector3D(0,0,1)};readonly Dictionary<Model3D,Guid> objectModels=new();readonly WallMeshBuilder wallMeshes=new();readonly StairMeshBuilder stairMeshes=new();ShellProject? project;Guid? selected;Point? orbitStart;Point? dragStart;Vec3? dragPositionStart,dragRotationStart,dragScaleStart;GizmoAxis activeAxis=GizmoAxis.None;TransformMode mode=TransformMode.Move;bool openingPlacement;bool openingDoor;float openingWidth=1,openingHeight=2.1f,openingSill;double yaw=.7,pitch=.55,distance=18;public event Action<Guid>? ObjectSelected;public event Action? ObjectTransformed;public event Action<Guid,float,float,float,bool>? WallOpeningRequested;public Viewport3DControl(){Background=new SolidColorBrush(Color.FromRgb(12,12,16));view.Camera=camera;view.Children.Add(new ModelVisual3D{Content=scene});Children.Add(view);MouseWheel+=Wheel;MouseRightButtonDown+=OrbitDown;MouseRightButtonUp+=OrbitUp;MouseLeftButtonDown+=LeftDown;MouseLeftButtonUp+=LeftUp;MouseMove+=Move;Loaded+=(_,_)=>RenderScene();}public void SetProject(ShellProject p,Guid? selectedId=null){project=p;selected=selectedId;RenderScene();}public void SetMode(TransformMode value){mode=value;openingPlacement=false;RenderScene();}public void BeginWallOpeningPlacement(bool door,float width,float height,float sill){openingPlacement=true;openingDoor=door;openingWidth=Math.Max(.1f,width);openingHeight=Math.Max(.1f,height);openingSill=door?0:Math.Max(0,sill);Cursor=Cursors.Cross;RenderScene();}public void CancelWallOpeningPlacement(){openingPlacement=false;Cursor=Cursors.Arrow;RenderScene();}public void RenderScene(){scene.Children.Clear();objectModels.Clear();scene.Children.Add(new AmbientLight(Color.FromRgb(105,105,120)));scene.Children.Add(new DirectionalLight(Colors.White,new Vector3D(-.4,.6,-1)));DrawGrid();if(project==null)return;foreach(var sceneObject in project.Objects){var model=Model(sceneObject,sceneObject.Id==selected);objectModels[model]=sceneObject.Id;scene.Children.Add(model);}if(!openingPlacement&&selected is Guid id){var selectedObject=project.Objects.FirstOrDefault(x=>x.Id==id);if(selectedObject!=null)DrawGizmo(selectedObject);}}GeometryModel3D Model(SceneObject o,bool active){MeshGeometry3D mesh;if(o.Type==SceneObjectType.Wall&&project!=null)mesh=wallMeshes.Build(o,project.WallOpenings.Where(x=>x.WallId==o.Id));else if(o.Type==SceneObjectType.Stairs)mesh=stairMeshes.Build(o);else mesh=BoxMesh(o.Scale);var color=active?Color.FromRgb(176,132,245):o.Type==SceneObjectType.Prop?Color.FromRgb(125,90,190):o.Type==SceneObjectType.Stairs?Color.FromRgb(130,96,180):Color.FromRgb(105,76,165);var mat=new DiffuseMaterial(new SolidColorBrush(color));var model=new GeometryModel3D(mesh,mat){BackMaterial=mat};var t=new Transform3DGroup();t.Children.Add(new RotateTransform3D(new AxisAngleRotation3D(new Vector3D(1,0,0),o.Rotation.X)));t.Children.Add(new RotateTransform3D(new AxisAngleRotation3D(new Vector3D(0,1,0),o.Rotation.Y)));t.Children.Add(new RotateTransform3D(new AxisAngleRotation3D(new Vector3D(0,0,1),o.Rotation.Z)));var z=o.Type==SceneObjectType.Wall?o.Position.Z-o.Scale.Z/2:o.Type==SceneObjectType.Stairs?o.Position.Z-o.Scale.Z/2:o.Position.Z;t.Children.Add(new TranslateTransform3D(o.Position.X,o.Position.Y,z));model.Transform=t;return model;}static MeshGeometry3D BoxMesh(Vec3 scale){var sx=Math.Max(.02,scale.X)/2;var sy=Math.Max(.02,scale.Y)/2;var sz=Math.Max(.02,scale.Z)/2;return new MeshGeometry3D{Positions=new Point3DCollection{new(-sx,-sy,-sz),new(sx,-sy,-sz),new(sx,sy,-sz),new(-sx,sy,-sz),new(-sx,-sy,sz),new(sx,-sy,sz),new(sx,sy,sz),new(-sx,sy,sz)},TriangleIndices=new Int32Collection{0,2,1,0,3,2,4,5,6,4,6,7,0,1,5,0,5,4,1,2,6,1,6,5,2,3,7,2,7,6,3,0,4,3,4,7}};}void DrawGizmo(SceneObject o){var origin=new Point3D(o.Position.X,o.Position.Y,o.Position.Z);var width=mode==TransformMode.Rotate?.09:.06;scene.Children.Add(Axis(origin,new Vector3D(2.2,0,0),Colors.Red,GizmoAxis.X,width));scene.Children.Add(Axis(origin,new Vector3D(0,2.2,0),Colors.LimeGreen,GizmoAxis.Y,width));scene.Children.Add(Axis(origin,new Vector3D(0,0,2.2),Colors.DodgerBlue,GizmoAxis.Z,width));}GeometryModel3D Axis(Point3D p,Vector3D d,Color c,GizmoAxis axis,double width){var m=Line(p,p+d,width,c);m.SetValue(FrameworkElement.TagProperty,axis);return m;}void DrawGrid(){for(int i=-20;i<=20;i++){scene.Children.Add(Line(new Point3D(i,-20,0),new Point3D(i,20,0),.01,Color.FromRgb(42,42,52)));scene.Children.Add(Line(new Point3D(-20,i,0),new Point3D(20,i,0),.01,Color.FromRgb(42,42,52)));}}GeometryModel3D Line(Point3D a,Point3D b,double width,Color color){var direction=b-a;var len=direction.Length;var mesh=new MeshGeometry3D{Positions=new Point3DCollection{new(-width,-len/2,0),new(width,-len/2,0),new(width,len/2,0),new(-width,len/2,0)},TriangleIndices=new Int32Collection{0,1,2,0,2,3}};var mat=new DiffuseMaterial(new SolidColorBrush(color));var m=new GeometryModel3D(mesh,mat){BackMaterial=mat};var angle=Math.Atan2(direction.Y,direction.X)*180/Math.PI-90;var t=new Transform3DGroup();t.Children.Add(new RotateTransform3D(new AxisAngleRotation3D(new Vector3D(0,0,1),angle)));if(Math.Abs(direction.Z)>Math.Abs(direction.X)+Math.Abs(direction.Y))t.Children.Add(new RotateTransform3D(new AxisAngleRotation3D(new Vector3D(1,0,0),90)));t.Children.Add(new TranslateTransform3D((a.X+b.X)/2,(a.Y+b.Y)/2,(a.Z+b.Z)/2));m.Transform=t;return m;}void OrbitDown(object s,MouseButtonEventArgs e){orbitStart=e.GetPosition(this);CaptureMouse();}void OrbitUp(object s,MouseButtonEventArgs e){orbitStart=null;if(activeAxis==GizmoAxis.None&&IsMouseCaptured)ReleaseMouseCapture();}void LeftDown(object s,MouseButtonEventArgs e){var hit=VisualTreeHelper.HitTest(view,e.GetPosition(view)) as RayMeshGeometry3DHitTestResult;if(hit?.ModelHit is not Model3D model)return;if(openingPlacement&&objectModels.TryGetValue(model,out var wallId)&&project!=null){var wall=project.Objects.FirstOrDefault(x=>x.Id==wallId);if(wall?.Type==SceneObjectType.Wall){var local=hit.PointHit;var inv=model.Transform?.Inverse;if(inv!=null)local=inv.Transform(hit.PointHit);var offset=(float)local.X+wall.Scale.X/2;offset=Math.Clamp(offset,openingWidth/2,Math.Max(openingWidth/2,wall.Scale.X-openingWidth/2));WallOpeningRequested?.Invoke(wall.Id,offset,openingWidth,openingHeight,openingDoor);selected=wall.Id;CancelWallOpeningPlacement();ObjectSelected?.Invoke(wall.Id);e.Handled=true;return;}}if(model.GetValue(FrameworkElement.TagProperty) is GizmoAxis axis&&axis!=GizmoAxis.None&&selected!=null){activeAxis=axis;dragStart=e.GetPosition(this);var selectedObject=project?.Objects.FirstOrDefault(x=>x.Id==selected);if(selectedObject!=null){dragPositionStart=selectedObject.Position;dragRotationStart=selectedObject.Rotation;dragScaleStart=selectedObject.Scale;}CaptureMouse();e.Handled=true;return;}if(objectModels.TryGetValue(model,out var id)){selected=id;ObjectSelected?.Invoke(id);RenderScene();e.Handled=true;}}void LeftUp(object s,MouseButtonEventArgs e){activeAxis=GizmoAxis.None;dragStart=null;dragPositionStart=dragRotationStart=dragScaleStart=null;if(orbitStart==null&&IsMouseCaptured)ReleaseMouseCapture();}void Move(object s,MouseEventArgs e){if(orbitStart!=null&&e.RightButton==MouseButtonState.Pressed){var mousePoint=e.GetPosition(this);yaw+=(mousePoint.X-orbitStart.Value.X)*.01;pitch=Math.Clamp(pitch+(mousePoint.Y-orbitStart.Value.Y)*.01,-1.35,1.35);orbitStart=mousePoint;UpdateCamera();return;}if(activeAxis==GizmoAxis.None||dragStart==null||selected==null||project==null||e.LeftButton!=MouseButtonState.Pressed)return;var selectedObject=project.Objects.FirstOrDefault(x=>x.Id==selected);if(selectedObject==null)return;var now=e.GetPosition(this);var raw=(float)((now.X-dragStart.Value.X-(now.Y-dragStart.Value.Y))*.015);if(mode==TransformMode.Move&&dragPositionStart is Vec3 startPosition){var next=activeAxis switch{GizmoAxis.X=>new Vec3(startPosition.X+raw,startPosition.Y,startPosition.Z),GizmoAxis.Y=>new Vec3(startPosition.X,startPosition.Y+raw,startPosition.Z),GizmoAxis.Z=>new Vec3(startPosition.X,startPosition.Y,startPosition.Z+raw),_=>startPosition};var g=project.Settings.GridSize;if(g>0)next=new Vec3(Snap(next.X,g),Snap(next.Y,g),Snap(next.Z,g));selectedObject.Position=next;}else if(mode==TransformMode.Rotate&&dragRotationStart is Vec3 startRotation){var degrees=MathF.Round(raw*15f)*5f;selectedObject.Rotation=activeAxis switch{GizmoAxis.X=>new Vec3(startRotation.X+degrees,startRotation.Y,startRotation.Z),GizmoAxis.Y=>new Vec3(startRotation.X,startRotation.Y+degrees,startRotation.Z),GizmoAxis.Z=>new Vec3(startRotation.X,startRotation.Y,startRotation.Z+degrees),_=>startRotation};}else if(mode==TransformMode.Scale&&dragScaleStart is Vec3 startScale){var amount=raw*.35f;selectedObject.Scale=activeAxis switch{GizmoAxis.X=>new Vec3(Math.Max(.05f,startScale.X+amount),startScale.Y,startScale.Z),GizmoAxis.Y=>new Vec3(startScale.X,Math.Max(.05f,startScale.Y+amount),startScale.Z),GizmoAxis.Z=>new Vec3(startScale.X,startScale.Y,Math.Max(.05f,startScale.Z+amount)),_=>startScale};}RenderScene();ObjectTransformed?.Invoke();}void Wheel(object s,MouseWheelEventArgs e){distance=Math.Clamp(distance-e.Delta/120.0,3,80);UpdateCamera();}void UpdateCamera(){var cp=Math.Cos(pitch);var pos=new Point3D(Math.Cos(yaw)*cp*distance,Math.Sin(yaw)*cp*distance,Math.Sin(pitch)*distance+3);camera.Position=pos;camera.LookDirection=new Vector3D(-pos.X,-pos.Y,1.5-pos.Z);}static float Snap(float v,float g)=>MathF.Round(v/g)*g;enum GizmoAxis{None,X,Y,Z}}
